contract InvMutTest is Test {
    EBU c;

    function setUp() public {
        c = new EBU();
    }

    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(to != address(0));
        vm.assume(to != address(c));

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory values = new uint256[](1);
        values[0] = amount;

        bool ok;
        bool ret;
        try c.transfer(from, to, tos, values) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
        }

        assertTrue(!ok || ret);
    }
}
